export const SITE_HEADER_CSS = ".site-header {\n  --header-ink: #172d3c;\n  --header-muted: #526575;\n  --header-line: #d6e0e6;\n  --header-accent: #205e54;\n  --header-highlight: #e8f2ef;\n  --header-gutter: clamp(1rem, 4vw, 2.5rem);\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  background: #fff;\n  border-bottom: 1px solid var(--header-line);\n}\n.header-inner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1.5rem;\n  max-width: 1240px;\n  min-height: 68px;\n  margin-inline: auto;\n  padding-inline: var(--header-gutter);\n}\n.site-header .site-logo {\n  display: inline-flex;\n  align-items: center;\n  gap: .5rem;\n  color: var(--header-ink);\n  font: 700 clamp(1.15rem, 2.5vw, 1.35rem)/1.25 Georgia, \"Times New Roman\", serif;\n  letter-spacing: -.025em;\n  text-decoration: none;\n  white-space: nowrap;\n}\n.site-logo-mark {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 36px;\n  height: 36px;\n  flex: none;\n  overflow: hidden;\n}\n.site-logo-mark img { display: block; width: 64px; height: 64px; max-width: none; flex: none; }\n.site-header .site-menu-toggle {\n  display: none;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  width: 44px;\n  height: 44px;\n  padding: 0;\n  border: 1px solid var(--header-line);\n  border-radius: 9px;\n  color: var(--header-ink);\n  background: #fff;\n  font: 500 1rem/1 system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  cursor: pointer;\n}\n.site-header .site-menu-toggle:hover { background: var(--header-highlight); }\n.site-header :is(a, button):focus-visible { outline: 2px solid var(--header-accent); outline-offset: 3px; }\n.site-header .nav-links {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  list-style: none;\n  padding: 0;\n  margin: 0;\n}\n.site-header .nav-links li { margin: 0; }\n.site-header .nav-links a {\n  display: flex;\n  align-items: center;\n  min-height: 44px;\n  padding: .45rem .65rem;\n  border-radius: 7px;\n  color: var(--header-muted);\n  font: 550 .875rem/1.35 system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  text-decoration: none;\n  white-space: nowrap;\n}\n.site-header .nav-links a:hover,\n.site-header .nav-links a[aria-current=\"page\"] { background: var(--header-highlight); color: var(--header-accent); }\n.site-header .nav-links a[href=\"/mon-accompagnement/\"] { color: var(--header-accent); font-weight: 700; }\n@media (840px < width <= 1050px) {\n  .header-inner { gap: .625rem; padding-inline: 1rem; }\n  .site-header .site-logo { font-size: 1.15rem; }\n  .site-header .nav-links { gap: 0; }\n  .site-header .nav-links a { padding-inline: .32rem; font-size: .82rem; }\n}\n@media (max-width: 840px) {\n  .header-inner { min-height: 64px; gap: .75rem; }\n  .site-header .site-menu-toggle { display: inline-flex; }\n  .site-navigation {\n    position: absolute;\n    inset: 100% 0 auto;\n    max-height: calc(100dvh - 64px);\n    overflow: auto;\n    background: #fff;\n    border-bottom: 1px solid var(--header-line);\n    box-shadow: 0 12px 24px rgb(23 45 60 / .08);\n    padding: .65rem var(--header-gutter) 1rem;\n  }\n  .site-navigation:not(.is-open) { display: none; }\n  .site-header .nav-links { flex-direction: column; align-items: stretch; }\n  .site-header .nav-links a { font-size: .95rem; padding-inline: .85rem; }\n}\n@media (max-width: 640px) {\n  .header-inner {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);\n  }\n  .site-header .site-logo { grid-column: 2; grid-row: 1; min-width: 44px; min-height: 44px; justify-content: center; }\n  .site-header .site-wordmark { display: none; }\n  .site-header .site-menu-toggle { grid-column: 3; grid-row: 1; justify-self: end; }\n}\n";
export const SITE_NAVIGATION_SCRIPT = "(function () {\n  'use strict';\n  var toggle = document.getElementById('site-menu-toggle');\n  var navigation = document.getElementById('site-navigation');\n  if (!toggle || !navigation) return;\n  function close() { navigation.classList.remove('is-open'); toggle.setAttribute('aria-expanded', 'false'); }\n  toggle.addEventListener('click', function () {\n    var open = toggle.getAttribute('aria-expanded') !== 'true';\n    navigation.classList.toggle('is-open', open);\n    toggle.setAttribute('aria-expanded', String(open));\n  });\n  navigation.addEventListener('click', function (event) { if (event.target.closest('a,button')) close(); });\n  document.addEventListener('click', function (event) { if (!event.target.closest('.site-header')) close(); });\n  document.addEventListener('keydown', function (event) {\n    if (event.key !== 'Escape' || toggle.getAttribute('aria-expanded') !== 'true') return;\n    close();\n    toggle.focus();\n    event.preventDefault();\n  });\n  var breakpoint = window.matchMedia('(max-width: 840px)');\n  if (breakpoint.addEventListener) breakpoint.addEventListener('change', close);\n  else if (breakpoint.addListener) breakpoint.addListener(close);\n})();\n";
